import React from 'react';
import { AlertTriangle, CheckCircle, ArrowRight } from 'lucide-react';

const ReportsTab = () => {
  const reports = [
    { id: 'REP-04', title: 'Illegal Disposal', cat: 'Waste', loc: 'Sector 4', status: 'pending' },
    { id: 'REP-09', title: 'Full Bin Report', cat: 'Waste', loc: 'Zone B', status: 'pending' },
  ];

  return (
    <div className="w-full max-w-lg animate-slide-up px-4">
      <h3 className="text-4xl font-black italic text-[#47510B] uppercase tracking-tighter mb-8">Citizen_Logs.</h3>
      <div className="space-y-4">
        {reports.map((r) => (
          <div key={r.id} className="bg-white p-6 rounded-[40px] border-4 border-[#47510B] flex items-center gap-6 group">
            <div className="w-14 h-14 rounded-2xl bg-[#AB1717] text-white flex items-center justify-center animate-pulse">
              <AlertTriangle size={28} />
            </div>
            <div className="flex-1">
              <h4 className="text-xl font-black text-[#47510B] uppercase italic leading-none">{r.title}</h4>
              <p className="text-[10px] font-bold opacity-40 mt-1 uppercase italic">{r.cat} // {r.loc}</p>
            </div>
            <button className="bg-[#CAD23C] p-3 rounded-xl border-2 border-[#47510B] font-black text-[10px] uppercase">
              Resolve
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ReportsTab;
